import ast, pathlib
for f in ["gates","openqasm","circuit","simulator","noise","optimizer","estimation"]:
    src = pathlib.Path(f"quantum_circuit/{f}.py").read_text()
    tree = ast.parse(src)
    imported = set()
    for n in ast.walk(tree):
        if isinstance(n, ast.ImportFrom) and n.module:
            for a in n.names:
                imported.add(a.asname or a.name)
        if isinstance(n, ast.Import):
            for a in n.names:
                imported.add((a.asname or a.name).split(".")[0])
    unused = [name for name in imported
              if name != "annotations" and not ast.walk]
    # crude name usage scan
    missing=[]
    for name in imported:
        if name in ("annotations",): continue
        used = len([1 for n in ast.walk(tree)
                    if isinstance(n, ast.Name) and n.id == name])
        attr = src.count("."+name)
        if used==0 and attr==0 and name not in src.replace(f"import {name}","").replace(f", {name}","").replace(f"{name},",""):
            missing.append(name)
    print(f, "possibly-unused:", missing)
